import{_ as r,a as e,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"六十四卦详读二：小畜履泰否至同人大有谦豫 · 09 小畜：力量有限时如何积蓄至11 泰：通达的时候更要维持条件","description":"对读《周易》与《周易正义》，理解第九至第十六卦的节制、礼履、通塞、共同体、丰有与谦豫。","frontmatter":{"title":"六十四卦详读二：小畜履泰否至同人大有谦豫 · 09 小畜：力量有限时如何积蓄至11 泰：通达的时候更要维持条件","description":"对读《周易》与《周易正义》，理解第九至第十六卦的节制、礼履、通塞、共同体、丰有与谦豫。","splitFrom":"life/personal/yijing/hexagrams-09-16.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"六十四卦详读二：小畜履泰否至同人大有谦豫","summary":"对读《周易》与《周易正义》，理解第九至第十六卦的节制、礼履、通塞、共同体、丰有与谦豫。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"六十四卦详读二：小畜履泰否至同人大有谦豫","link":"/life/personal/yijing/hexagrams-09-16"},"next":{"text":"六十四卦详读二：小畜履泰否至同人大有谦豫 · 12 否：闭塞之中保存原则至14 大有：拥有越多，越须承担分配责任","link":"/life/personal/yijing/hexagrams-09-16-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"六十四卦详读二：小畜履泰否至同人大有谦豫","link":"/life/personal/yijing/hexagrams-09-16"},"next":{"text":"六十四卦详读二：小畜履泰否至同人大有谦豫 · 12 否：闭塞之中保存原则至14 大有：拥有越多，越须承担分配责任","link":"/life/personal/yijing/hexagrams-09-16-part-02"}},"headers":[],"relativePath":"life/personal/yijing/hexagrams-09-16-part-01.md","filePath":"life/personal/yijing/hexagrams-09-16-part-01.md"}'),o={name:"life/personal/yijing/hexagrams-09-16-part-01.md"};function s(i,t,d,p,g,l){return e(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="六十四卦详读二-小畜履泰否至同人大有谦豫-·-09-小畜-力量有限时如何积蓄至11-泰-通达的时候更要维持条件" tabindex="-1">六十四卦详读二：小畜履泰否至同人大有谦豫 · 09 小畜：力量有限时如何积蓄至11 泰：通达的时候更要维持条件 <a class="header-anchor" href="#六十四卦详读二-小畜履泰否至同人大有谦豫-·-09-小畜-力量有限时如何积蓄至11-泰-通达的时候更要维持条件" aria-label="Permalink to &quot;六十四卦详读二：小畜履泰否至同人大有谦豫 · 09 小畜：力量有限时如何积蓄至11 泰：通达的时候更要维持条件&quot;">​</a></h1><p><a href="/life/personal/yijing/hexagrams-09-16">返回分篇目录</a></p><p>本组特别适合成对阅读：小畜与履讨论限制和行进，泰与否呈现通塞，同人与大有讨论联结和拥有，谦与豫则观察自处及群体情绪。所谓“好卦”也包含风险，“坏卦”中也可能出现可行之道。</p><p>本文逐卦对读《周易》经传与王弼注、孔颖达疏《周易正义》。引文是古籍原文，表格解释与读法为本篇白话概括；通行字句参照《正义》，如小畜的“輿說輻”、大有的“匪其彭”，并提示异文。标点属整理，不应误以为古本原有。占断是古代文化材料，本文讨论其结构与思想，不据此预测现实结果。</p><h2 id="六十四卦详读二-小畜履泰否至同人大有谦豫" tabindex="-1">六十四卦详读二：小畜履泰否至同人大有谦豫 <a class="header-anchor" href="#六十四卦详读二-小畜履泰否至同人大有谦豫" aria-label="Permalink to &quot;六十四卦详读二：小畜履泰否至同人大有谦豫 {#六十四卦详读二-小畜履泰否至同人大有谦豫}&quot;">​</a></h2><p>本组特别适合成对阅读：小畜与履讨论限制和行进，泰与否呈现通塞，同人与大有讨论联结和拥有，谦与豫则观察自处及群体情绪。所谓“好卦”也包含风险，“坏卦”中也可能出现可行之道。</p><p>本文逐卦对读《周易》经传与王弼注、孔颖达疏《周易正义》。引文是古籍原文，表格解释与读法为本篇白话概括；通行字句参照《正义》，如小畜的“輿說輻”、大有的“匪其彭”，并提示异文。标点属整理，不应误以为古本原有。占断是古代文化材料，本文讨论其结构与思想，不据此预测现实结果。</p><h2 id="gua-09" tabindex="-1">09 小畜：力量有限时如何积蓄 <a class="header-anchor" href="#gua-09" aria-label="Permalink to &quot;09 小畜：力量有限时如何积蓄 {#gua-09}&quot;">​</a></h2><p><strong>卦符：䷈　上卦：巽 ☴（风、入）　下卦：乾 ☰（天、健）。畜读 xù，兼有蓄聚、畜止义。</strong></p><p><strong>卦辞原文</strong>：小畜：亨。密雲不雨，自我西郊。</p><p><strong>白话概括</strong>：云密而雨未成，表现力量已有聚集、施用仍受限制。《正义》着重巽柔不能像艮那样强力止住乾健，所畜有限；后来的积蓄义读法也应保留“尚未充分发挥”的条件。西郊是经文意象，不是告诉读者向西投资或等待天气应验。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九：復自道，何其咎，吉。</td><td>从合宜的路径返回，何来咎责？面对限制，退回正道可能比继续强行推进更稳妥。</td></tr><tr><td>九二：牽復，吉。</td><td>与同类相牵而复，保持中道。相互提醒、共同调整可以有益，但不能把任何结伴都当成吉。</td></tr><tr><td>九三：輿說輻，夫妻反目。</td><td>车失去关键部件而停，关系也转为对立。“说”读脱；輻、輹等有异文，皆不可忽略行进受阻之象。</td></tr><tr><td>六四：有孚，血去惕出，无咎。</td><td>以诚信改善相处，使伤害与恐惧离开。重点在关系得以协调，不在柔者凭身份自然获胜。</td></tr><tr><td>九五：有孚攣如，富以其鄰。</td><td>相互信任、紧密联结，使资源不只独占。攣是连结之意，不应把富只读成个人财富上涨。</td></tr><tr><td>上九：既雨既處，尚德載，婦貞厲，月幾望，君子征凶。</td><td>雨已下、局面已定，积聚来到近满之处；再进反有危险。含古代婚姻与阴阳秩序，不宜照搬为性别规范。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“風行天上，小畜；君子以懿文德。”</p><p><strong>解释</strong>：取风行天上之象，先修美可积累的文德。限制之中仍能做细致工作，但文饰也不是掩盖实质不足。与大畜“多识前言往行”相比，小畜更突显力量尚小、作用尚未充分展开。</p><p><strong>整体读法与误区</strong>：读全卦要看到“不雨”到“既雨”的变化，以及既雨之后仍不宜继续征进。解决了一个阶段的问题，不代表可以无限扩张。王、孔的解释主要谈畜止，不能只把卦名解释成小额存款；“密云不雨”也不是必然失败，而是提醒区分酝酿、实现和过满三个状态。</p><p><strong>细读线索</strong>：六四是全卦唯一阴爻，处在外卦之初，古注用它解释柔如何畜刚。但初、二仍可复行，九三受阻更明显，说明一个结构中的限制并不平均落在所有位置上。四、五写孚，又把力量关系转成能否互信的问题。读者可循云与雨观察聚积是否成形，再循车与夫妻观察运行和关系是否协调；这些意象相互补充，不能只抓住其中一个来作万能解释。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B0%8F%E7%95%9C" target="_blank" rel="noopener noreferrer">《周易·小畜》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/02%E5%B0%8F%E7%95%9C" target="_blank" rel="noopener noreferrer">《周易正义·上经需传卷二·小畜》</a>。</p><h2 id="gua-10" tabindex="-1">10 履：在危险中保持分寸 <a class="header-anchor" href="#gua-10" aria-label="Permalink to &quot;10 履：在危险中保持分寸 {#gua-10}&quot;">​</a></h2><p><strong>卦符：䷉　上卦：乾 ☰（天）　下卦：兑 ☱（泽、悦）。履是践履，也与礼的秩序相联。</strong></p><p><strong>卦辞原文</strong>：履虎尾，不咥人，亨。</p><p><strong>白话概括</strong>：踩到虎尾而未被咬，用强烈危险意象表达谨慎行事的可能。《正义》从兑悦应乾、柔履刚解释，但六三明明又说咥人，说明卦辞总论不能自动担保每个具体位置。礼履可帮助协调关系，却不是靠讨好强者就能获得绝对安全。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九：素履，往无咎。</td><td>以朴素本分行进，不借虚饰冒充能力。素履不是贫困必然高尚，而是不失真实所能。</td></tr><tr><td>九二：履道坦坦，幽人貞吉。</td><td>行于平坦之道，安静而不受名利扰动者守正得吉。安稳并不一定需要显赫位置。</td></tr><tr><td>六三：眇能視，跛能履，履虎尾，咥人，凶。武人為于大君。</td><td>视行能力受限却自以为足够，强行犯险。古代身体比喻旨在揭示能力与自信失配，不是评价残障者的价值。</td></tr><tr><td>九四：履虎尾，愬愬終吉。</td><td>同样面临危险，因为惧慎而能有较好结局。恐惧有时提供必要的自我约束。</td></tr><tr><td>九五：夬履，貞厲。</td><td>以决断方式行事，即使有正当位置仍有危险。权力与果断不能代替审慎。</td></tr><tr><td>上九：視履考詳，其旋元吉。</td><td>回看走过的路，考察得失与周全程度。“旋”的解释有旋归、周遍等说，不宜只译成凯旋。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“上天下澤，履；君子以辨上下，定民志。”</p><p><strong>解释</strong>：天地泽的高下被古传用于说明礼制的分际与秩序。现代可以借此思考角色与责任要清楚，但不能据古代上下等级证明现实中的不平等必然合理。</p><p><strong>整体读法与误区</strong>：六三、九四都履虎尾，差别在对自身条件与风险的态度；九五居中且正，也没有被免除“厉”。因此履不是教人消除一切不确定性，而是让行动和能力相称。上九再要求回顾，形成“起步真实—行中知戒—结束复核”的阅读线索，不能只把“咥人”当作待应验的灾难。</p><p><strong>细读线索</strong>：履卦的柔爻只有六三，它成为古注说明成卦之义的重要位置；但成卦的关键并不意味着该爻自身最好。卦辞的不咥与六三的咥人正好显示总论和局部评价的区别。九四愬愬能终吉，九五夬履却仍厉，也使谨慎与果断不能固定排序。判断要落在谁正在做什么、处于何种关系之中，而不是把某种性格永久命名为优点或缺点。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%B1%A5" target="_blank" rel="noopener noreferrer">《周易·履》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/02%E5%B1%A5" target="_blank" rel="noopener noreferrer">《周易正义·上经需传卷二·履》</a>。</p><h2 id="gua-11" tabindex="-1">11 泰：通达的时候更要维持条件 <a class="header-anchor" href="#gua-11" aria-label="Permalink to &quot;11 泰：通达的时候更要维持条件 {#gua-11}&quot;">​</a></h2><p><strong>卦符：䷊　上卦：坤 ☷（地）　下卦：乾 ☰（天）。</strong></p><p><strong>卦辞原文</strong>：泰：小往大來，吉亨。</p><p><strong>白话概括</strong>：天地相交，上下能够沟通，形成通泰。“小、大”在《彖》《正义》中联系阴阳与君子小人的解释系统，并非简单说少花钱多赚钱。《正义》还提醒通达过甚可能失节，所以泰并没有取消裁成、辅相的需要。顺利是一种有条件的关系，不是永久状态。</p><table tabindex="0"><thead><tr><th>爻位与原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九：拔茅茹，以其彙，征吉。</td><td>拔茅时根相牵连，同类可以相携而进。茹指相连的根，彙指类聚。</td></tr><tr><td>九二：包荒，用馮河，不遐遺，朋亡，得尚于中行。</td><td>包容荒远，具备渡难的勇气，不遗弃远人，也不困于私党。馮河是徒涉之象，不能单独读成鼓励冒险。</td></tr><tr><td>九三：无平不陂，无往不復，艱貞无咎。勿恤其孚，于食有福。</td><td>平处会有坡折，去者也可能返回；在转折前守正、保持诚信。变化不是对每个日期的精确预测。</td></tr><tr><td>六四：翩翩，不富以其鄰，不戒以孚。</td><td>与邻近者共同趋向，不靠财富驱使，也不待告戒而相孚。古注结合群阴相应说明，不能简化为朋友越多越好。</td></tr><tr><td>六五：帝乙歸妹，以祉，元吉。</td><td>借帝乙嫁女的叙事说明贵而能下、关系相接。具体史事细节有争议，不宜据此补造完整故事。</td></tr><tr><td>上六：城復于隍，勿用師，自邑告命，貞吝。</td><td>城墙倒回城壕，通泰的基础已经败坏；再靠军事强撑无益，应先处理自身。全卦以衰变收尾。</td></tr></tbody></table><p><strong>《大象》原文</strong>：“天地交，泰；后以財成天地之道，輔相天地之宜，以左右民。”</p><p><strong>解释</strong>：“财成”通裁成，指适当安排；“辅相”是辅助配合，“左右”是扶助。古传要求主政者在自然条件与民众生活之间作出合宜安排，通泰不是放任一切自行运转。</p><p><strong>整体读法与误区</strong>：泰最不应遗漏的两爻是九三和上六：前者在盛时提醒反复，后者呈现基础崩解。与<a href="/life/personal/yijing/hexagrams-09-16-part-02#gua-12">否卦</a>配读，会看到通与塞在全卦中都有转机，但绝不是“好运时不用做事，坏运气等一等就好”。关键在关系能否继续互通、制度是否仍能支撑。</p><p><strong>细读线索</strong>：泰的下卦三阳与上卦三阴，古注常用内健外顺解释其所以相交。这里天在下、地在上，并不是一张物理天空倒置的图，而是借两种力量的趋向说明相接。六五借婚嫁写连接，九二写不遐遗、朋亡，反复要求开放而不偏私。若只看到天地和谐而忽略人怎样维持连接，便把泰的政治与伦理要求读没了；通达还需要具体的裁成与辅助。</p><p><strong>古籍对读</strong>：<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%B3%B0" target="_blank" rel="noopener noreferrer">《周易·泰》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/02%E6%B3%B0" target="_blank" rel="noopener noreferrer">《周易正义·上经需传卷二·泰》</a>。</p>',37)])])}const f=r(o,[["render",s]]);export{c as __pageData,f as default};
